// EasyPost signs the raw body: X-Hmac-Signature = "hmac-sha256-hex=" + hex HMAC-SHA256,
// keyed with the webhook secret normalized to NFKD (as EasyPost's client libraries do).
const crypto = require('crypto');
const secret = $vars.EASYPOST_WEBHOOK_SECRET; // the secret set on the EasyPost webhook
if (!secret) throw new Error('EASYPOST_WEBHOOK_SECRET is not configured');

const item = $input.first();
let rawBody;
if (item.binary && item.binary.data) {
  // rawBody: true puts the exact bytes in binary.data (inline base64, or a stored file id).
  rawBody = item.binary.data.id
    ? await this.helpers.getBinaryDataBuffer(0, 'data')
    : Buffer.from(item.binary.data.data, 'base64');
} else {
  rawBody = Buffer.from(JSON.stringify(item.json.body || {}), 'utf8');
}
const headers = item.json.headers || {};
const provided = String(headers['x-hmac-signature'] || headers['X-Hmac-Signature'] || '').trim().toLowerCase();
const key = Buffer.from(String(secret).normalize('NFKD'), 'utf8');
const expected = 'hmac-sha256-hex=' + crypto.createHmac('sha256', key).update(rawBody).digest('hex');

const a = Buffer.from(provided);
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid X-Hmac-Signature — dropping event');
}
return [{ json: JSON.parse(rawBody.toString('utf8')) }];

// Only tracker events matter; anything else stops here (EasyPost already got its 200).
// The latest checkpoint is the last entry of tracking_details.
const event = $input.first().json;
if (!['tracker.updated', 'tracker.created'].includes(event.description)) return [];
const tracker = event.result || {};
if (!tracker.tracking_code) return [];
const details = tracker.tracking_details || [];
const last = details.length ? details[details.length - 1] : {};
return [{ json: {
  tracking_code: tracker.tracking_code,
  status: tracker.status || null,
  status_detail: tracker.status_detail || null,
  carrier: tracker.carrier || null,
  est_delivery_date: tracker.est_delivery_date || null,
  message: last.message || null,
  occurred_at: last.datetime || null,
  public_url: tracker.public_url || null,
} }];

// Sign the exact JSON string sent to ERPNext. ERPNext recomputes
// HMAC-SHA256(raw_body, shipping webhook secret) and compares hex digests.
const crypto = require('crypto');
const secret = $vars.SHIPPING_WEBHOOK_SECRET; // same value as ilL-Shipping-Settings webhook secret
if (!secret) throw new Error('SHIPPING_WEBHOOK_SECRET is not configured');
return $input.all().map(item => {
  const body = JSON.stringify(item.json);
  const signature = crypto.createHmac('sha256', secret).update(body, 'utf8').digest('hex');
  return { json: { body, signature, tracking_code: item.json.tracking_code } };
});

// 404 = no Shipment holds this tracking number (e.g. a label bought outside ERPNext):
// nothing to retry, so the run ends quietly. Any other non-2xx fails the execution so it
// shows in n8n's execution list (and an error workflow can alert on it).
const res = $input.first().json;
const status = Number(res.statusCode || 0);
const tracking = $('Sign Event (HMAC)').first().json.tracking_code;
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep text */ } }
if (status === 404) return [{ json: { tracking_code: tracking, skipped: 'not_found', response: body } }];
if (status < 200 || status >= 300) {
  const detail = typeof body === 'string' ? body : JSON.stringify(body);
  throw new Error(`ERPNext receive_tracking_event returned HTTP ${status} for ${tracking}: ${String(detail).slice(0, 300)}`);
}
return [{ json: { tracking_code: tracking, response: body } }];
